                    Key.Menu -> { menu = true; true }
                    Key.DirectionUp, Key.ChannelUp -> { index = (index - 1 + channels.size) % channels.size; true }
                    Key.DirectionDown, Key.ChannelDown -> { index = (index + 1) % channels.size; true }
