76	@Composable
77	fun App() {
78	    val context = LocalContext.current
79	    val store = remember { SourceStore(context) }
80	    var sources by remember { mutableStateOf(store.load()) }
81	    var activeId by remember { mutableStateOf(store.activeId()) }
82	    val active = sources.firstOrNull { it.id == activeId } ?: sources.firstOrNull()
83	    var mode by remember { mutableIntStateOf(0) } // 0 TV, 1 movies, 2 series, 3 settings
84	    var switched by remember { mutableStateOf(false) } // after switching modes, focus the switcher once instead of the list
85	    var settingsFocus by remember { mutableStateOf<String?>(null) } // source row (or ADD_SOURCE) to focus in settings
86	    var autoplay by remember { mutableStateOf(true) } // auto-play the last channel only on app start
87	    fun update(list: List<Account>, newActive: String?) {
88	        sources = list; activeId = newActive; store.save(list, newActive)
89	    }
90	    val header = @Composable { ModeSwitch(mode, onMode = { mode = it; switched = true }, focus = switched, onFocused = { switched = false }) }
91	
92	    if (active == null) {
93	        // First run (or all sources deleted): set up a source or try the demo.
94	        SourceForm(initial = null, onSave = { update(listOf(it), it.id); mode = 0; switched = false }, onCancel = null)
95	        return
96	    }
97	    key(active) { // switching or editing the active source rebuilds everything for it
98	        val x = remember { Xtream(active) }
99	        when (mode) {
100	            0 -> BrowseScreen(
101	                x, header, autoFocus = !switched, autoplay = autoplay,
102	                onAutoplayed = { autoplay = false },
103	                onManageSources = { mode = 3; switched = true },
104	            )
105	            3 -> SettingsScreen(
106	                header, sources, active, focusId = settingsFocus, onFocusId = { settingsFocus = it },
107	                onActivate = { autoplay = false; update(sources, it.id); mode = 0; switched = false },
108	                onSave = { saved ->
109	                    val list = if (sources.any { it.id == saved.id }) sources.map { if (it.id == saved.id) saved else it } else sources + saved
110	                    if (sources.none { it.id == saved.id }) store.deleteData(saved) // fresh id: make sure nothing stale is left
111	                    update(list, activeId ?: saved.id)
112	                    settingsFocus = saved.id
113	                },
114	                onDelete = { gone ->
115	                    store.deleteData(gone)
116	                    val index = sources.indexOf(gone)
117	                    val list = sources - gone
118	                    settingsFocus = (list.getOrNull(index) ?: list.getOrNull(index - 1))?.id ?: ADD_SOURCE
119	                    update(list, if (gone == active) list.firstOrNull()?.id else active.id)
120	                },
121	            )
122	            // key: movies and series must not share state (selected category, continue-watching list, …)
123	            else -> key(mode) { VodScreen(x, series = mode == 2, header, autoFocus = !switched) }
