152	/**
153	 * Text input for the remote: a focusable box that shows the value; OK switches to editing and opens the keyboard.
154	 * (A plain text field would pop up the full-screen Fire TV keyboard as soon as D-pad focus touches it.)
155	 */
156	@Composable
157	fun Field(
158	    label: String,
159	    value: String,
160	    type: KeyboardType = KeyboardType.Text,
161	    password: Boolean = false,
162	    imeAction: ImeAction = ImeAction.Next,
163	    onTyping: (Boolean) -> Unit = {}, // true from opening the keyboard until focus is safely back (see BrowseScreen)
164	    onChange: (String) -> Unit,
165	) {
166	    var editing by remember { mutableStateOf(false) }
167	    var focused by remember { mutableStateOf(false) }
168	    val keyboard = LocalSoftwareKeyboardController.current
169	    val editor = remember { FocusRequester() }
170	    val idle = remember { FocusRequester() }
171	    val focusManager = LocalFocusManager.current
172	    var leaving by remember { mutableStateOf(false) } // focus moves on deliberately (Next / D-pad up/down)
173	    var refocus by remember { mutableIntStateOf(0) }
174	    val box = Modifier.fillMaxWidth().height(52.dp)
175	    val shape = RoundedCornerShape(8.dp)
176	    Column(Modifier.width(480.dp)) {
177	        Text(label, style = MaterialTheme.typography.labelMedium)
178	        if (editing) {
179	            BasicTextField(
180	                value = value,
181	                onValueChange = onChange,
182	                singleLine = true,
183	                textStyle = TextStyle(color = Color.White, fontSize = 18.sp),
184	                cursorBrush = SolidColor(Accent),
185	                visualTransformation = if (password) PasswordVisualTransformation() else VisualTransformation.None,
186	                keyboardOptions = KeyboardOptions(keyboardType = type, imeAction = imeAction),
187	                keyboardActions = KeyboardActions(
188	                    onNext = { leaving = true; focusManager.moveFocus(FocusDirection.Down) },
189	                    onSearch = { keyboard?.hide() },
190	                ),
191	                modifier = box
192	                    .focusRequester(editor)
193	                    .onFocusChanged { // leave editing only after having had focus (it also reports "unfocused" on attach)
194	                        if (it.isFocused) focused = true
195	                        else if (focused) {
196	                            // Closing the keyboard with Back drops focus somewhere else: bring it back to this field.
197	                            focused = false; editing = false
198	                            if (!leaving) refocus++
199	                            leaving = false
200	                        }
201	                    }
202	                    .onPreviewKeyEvent { e ->
203	                        if (e.type != KeyEventType.KeyDown) false
204	                        else when (e.key) {
205	                            Key.DirectionCenter, Key.Enter -> { keyboard?.show(); true } // reopen after Back
206	                            // The text field swallows Up/Down itself, so move on explicitly.
207	                            Key.DirectionUp, Key.DirectionDown -> {
208	                                leaving = true
209	                                focusManager.moveFocus(if (e.key == Key.DirectionUp) FocusDirection.Up else FocusDirection.Down)
210	                                true
211	                            }
212	                            // Back would otherwise become a focus exit that lands anywhere (e.g. on another category).
213	                            Key.Back -> { keyboard?.hide(); editing = false; refocus++; true }
214	                            else -> false
215	                        }
216	                    }
217	                    .border(2.dp, Accent, shape)
218	                    .padding(horizontal = 12.dp, vertical = 14.dp),
219	            )
220	            LaunchedEffect(Unit) { onTyping(true); editor.requestFocus(); keyboard?.show() }
221	        } else {
222	            LaunchedEffect(refocus) {
223	                // Fire OS closes the keyboard on Back without telling us and drops focus anywhere: take it back.
224	                if (refocus > 0) { awaitFrame(); runCatching { idle.requestFocus() } }
225	                onTyping(false)
226	            }
227	            Surface(
228	                onClick = { editing = true },
229	                modifier = box.focusRequester(idle),
230	                shape = ClickableSurfaceDefaults.shape(shape),
231	                scale = ClickableSurfaceDefaults.scale(focusedScale = 1f),
232	                colors = ClickableSurfaceDefaults.colors(
233	                    containerColor = Color.Transparent, focusedContainerColor = Color.White.copy(alpha = 0.06f),
234	                    contentColor = Color.White, focusedContentColor = Color.White,
235	                ),
236	                border = ClickableSurfaceDefaults.border(
237	                    border = Border(androidx.compose.foundation.BorderStroke(2.dp, Color.DarkGray), shape = shape),
238	                    focusedBorder = Border(androidx.compose.foundation.BorderStroke(2.dp, Accent), shape = shape),
239	                ),
240	            ) {
241	                Text(
242	                    if (password) "•".repeat(value.length) else value,
243	                    Modifier.align(Alignment.CenterStart).padding(horizontal = 12.dp),
244	                    fontSize = 18.sp, maxLines = 1,
245	                )
246	            }
247	        }
248	    }
249	}
