251	@Composable
252	fun BrowseScreen(
253	    x: Xtream,
254	    header: @Composable () -> Unit,
255	    autoFocus: Boolean,
256	    autoplay: Boolean,
257	    onAutoplayed: () -> Unit,
258	    onManageSources: () -> Unit,
259	) {
260	    var categories by remember { mutableStateOf<List<Category>?>(null) }
261	    var all by remember { mutableStateOf<List<Channel>>(emptyList()) }
262	    var byCategory by remember { mutableStateOf<Map<String, List<Channel>>>(emptyMap()) }
263	    val context = LocalContext.current
264	    val favPrefs = context.sourcePrefs("favorites", x.account)
265	    val lastPrefs = context.sourcePrefs("last", x.account)
266	    var favorites by remember { mutableStateOf(favPrefs.getStringSet("ids", emptySet())!!.toSet()) }
267	    fun toggleFavorite(ch: Channel) {
268	        val id = ch.id.toString()
269	        favorites = if (id in favorites) favorites - id else favorites + id
270	        favPrefs.edit().putStringSet("ids", favorites).apply()
271	    }
272	    // Recently watched channel ids, newest first.
273	    fun readRecent() = lastPrefs.getString("recent", "")!!.split(',').mapNotNull { it.toIntOrNull() }
274	    var recent by remember { mutableStateOf(readRecent()) }
275	    val catPrefs = context.sourcePrefs("categories", x.account)
276	    var hidden by remember { mutableStateOf(catPrefs.getStringSet("hidden", emptySet())!!.toSet()) }
277	    var showHidden by remember { mutableStateOf(false) }
278	    fun toggleHidden(cat: Category) {
279	        hidden = if (cat.id in hidden) hidden - cat.id else hidden + cat.id
280	        catPrefs.edit().putStringSet("hidden", hidden).apply()
281	    }
282	    var error by remember { mutableStateOf<String?>(null) }
283	    var selected by remember { mutableStateOf<String?>(null) }
284	    var playing by remember { mutableStateOf<Int?>(null) } // index within the current category
285	    var returnTo by remember { mutableStateOf<Int?>(null) }
286	    var refocus by remember { mutableIntStateOf(0) } // re-run the focus restore even if returnTo is unchanged
287	    val epg = remember { mutableStateMapOf<Int, List<Programme>>() } // stream_id -> programmes, cached for the session
288	    val lock = remember(x) { Lock(context, x.account) }
289	    var menu by remember { mutableStateOf<Category?>(null) } // long-press menu
290	    var gate by remember { mutableStateOf<(() -> Unit)?>(null) } // PIN prompt, runs the action on success
291	    var focusCat by remember { mutableStateOf<String?>(null) } // category to refocus after menu/PIN
292	    var archiveOf by remember { mutableStateOf<Channel?>(null) } // catch-up list open for this channel
293	    var replay by remember { mutableStateOf<Playback?>(null) } // catch-up recording playing
294	    var liveAfter by remember { mutableStateOf<Channel?>(null) } // start-over: go live when the recording runs out
295	    var backToLive by remember { mutableStateOf(false) } // start-over came from the live player: Back returns there
296	    var query by remember { mutableStateOf("") }
297	    var typing by remember { mutableStateOf(false) } // search keyboard open: stray focus must not switch the category
298	    val searchIndex = remember(all) { all.map { it to searchKey(it.name) } }
299	    // Locked categories show no channels, also not via favourites or recently watched.
300	    fun channelsOf(cat: String?, closed: Set<String>) =
301	        when (cat) {
302	            in closed -> emptyList()
303	            SEARCH -> searchKey(query.trim()).let { q ->
304	                if (q.length < 2) emptyList()
305	                else searchIndex.asSequence().filter { (ch, key) -> q in key && ch.categoryId !in closed }.map { it.first }.take(300).toList()
306	            }
307	            FAVORITES -> all.filter { it.id.toString() in favorites && it.categoryId !in closed }
308	            RECENT -> all.associateBy { it.id }.let { byId -> recent.mapNotNull { byId[it] }.filter { it.categoryId !in closed } }
309	            else -> byCategory[cat].orEmpty()
310	        }
311	    val loadingFailed = stringResource(R.string.loading_failed)
312	
313	    LaunchedEffect(x) {
314	        var started = false
315	        runCatching {
316	            // Cache first, then server.
317	            x.loadLists(context.cacheDir, listOf("get_live_categories", "get_live_streams")) { (catJson, chanJson) ->
318	                val (cats, chans) = withContext(Dispatchers.Default) { x.parseCategories(catJson) to x.parseChannels(chanJson) }
319	                all = chans
320	                byCategory = chans.groupBy { it.categoryId }
321	                categories = cats.filter { byCategory[it.id] != null }
322	                if (started) return@loadLists
323	                started = true
324	                if (autoplay) {
325	                    onAutoplayed()
326	                    // Start straight into the last watched channel if it still exists.
327	                    val lastCategory = lastPrefs.getString("category", null)
328	                    val last = channelsOf(lastCategory, lock.closedIds("live", cats)).indexOfFirst { it.id == lastPrefs.getInt("channel", -1) }
329	                    if (last >= 0) {
330	                        selected = lastCategory
331	                        playing = last
332	                        return@loadLists
333	                    }
334	                }
335	                selected = if (favorites.isNotEmpty()) FAVORITES else categories?.firstOrNull()?.id
336	            }
337	        }.onFailure { if (!started) error = it.message ?: loadingFailed }
338	    }
339	
340	    val loaded = categories
341	    if (loaded == null) {
342	        Column(Modifier.fillMaxSize(), Arrangement.Center, Alignment.CenterHorizontally) {
343	            Text(error ?: stringResource(R.string.loading_channels))
344	            if (error != null) Button(onClick = onManageSources, Modifier.padding(top = 16.dp)) { Text(stringResource(R.string.manage_sources)) }
345	        }
346	        return
347	    }
348	    val hiddenCount = loaded.count { it.id in hidden }
349	    val favoritesLabel = stringResource(R.string.favorites)
350	    val recentLabel = stringResource(R.string.recent)
351	    val hiddenLabel = if (showHidden) stringResource(R.string.hide_hidden) else stringResource(R.string.hidden_count, hiddenCount)
352	    val searchLabel = stringResource(R.string.search)
353	    val cats = buildList {
354	        add(Category(SEARCH, searchLabel))
355	        if (favorites.isNotEmpty()) add(Category(FAVORITES, favoritesLabel))
356	        if (recent.isNotEmpty()) add(Category(RECENT, recentLabel))
357	        addAll(if (showHidden) loaded else loaded.filter { it.id !in hidden })
358	        if (hiddenCount > 0) add(Category(TOGGLE_HIDDEN, hiddenLabel))
359	    }
360	    val closed = lock.closedIds("live", loaded)
361	    val channels = remember(selected, all, favorites, recent, closed, query) { channelsOf(selected, closed) }
362	    val firstCategory = remember { FocusRequester() }
363	    val catFocus = remember { FocusRequester() }
364	    LaunchedEffect(menu == null && gate == null) {
365	        if (menu == null && gate == null && focusCat != null) { awaitFrame(); runCatching { catFocus.requestFocus() } }
366	    }
367	    val channelFocus = remember { FocusRequester() }
368	    val channelList = rememberLazyListState()
369	
370	    LaunchedEffect(Unit) { awaitFrame(); if (autoFocus && playing == null) runCatching { firstCategory.requestFocus() } }
371	    LaunchedEffect(returnTo, refocus) {
372	        val i = returnTo ?: return@LaunchedEffect
373	        channelList.scrollToItem(i)
374	        awaitFrame()
375	        runCatching { channelFocus.requestFocus() }
376	    }
377	
378	    Box(Modifier.fillMaxSize()) {
379	        Row(Modifier.fillMaxSize().padding(24.dp), horizontalArrangement = Arrangement.spacedBy(24.dp)) {
380	            Column(Modifier.width(260.dp)) {
381	                header()
382	                Spacer(Modifier.height(12.dp))
383	                LazyColumn(verticalArrangement = Arrangement.spacedBy(4.dp)) {
384	                    itemsIndexed(cats, key = { _, c -> c.id }) { i, cat ->
385	                        val special = cat.id == SEARCH || cat.id == FAVORITES || cat.id == RECENT || cat.id == TOGGLE_HIDDEN
386	                        CategoryItem(
387	                            cat,
388	                            selected = cat.id == selected,
389	                            dim = cat.id in hidden || cat.id == TOGGLE_HIDDEN,
390	                            locked = !special && lock.isLocked("live", cat),
391	                            onClick = {
392	                                if (cat.id == TOGGLE_HIDDEN) showHidden = !showHidden
393	                                else if (cat.id in closed) { focusCat = cat.id; gate = {} }
394	                            },
395	                            onLongClick = { if (!special) { focusCat = cat.id; menu = cat } },
396	                            modifier = Modifier
397	                                // Start on the selected category (not on Search at the top).
398	                                .then(if (cat.id == selected || selected == null && i == 0) Modifier.focusRequester(firstCategory) else Modifier)
399	                                .then(if (cat.id == focusCat) Modifier.focusRequester(catFocus) else Modifier)
400	                                .onFocusChanged { if (it.isFocused && cat.id != TOGGLE_HIDDEN && !typing) selected = cat.id },
401	                        )
402	                    }
403	                }
404	            }
405	            val now = rememberNow()
406	            val start = guideStart(now)
407	            Column(Modifier.weight(1f)) {
408	                GuideHeader(start, now)
409	                if (selected in closed) LockedHint()
410	                if (selected == SEARCH) {
411	                    Field(stringResource(R.string.search_hint_channels), query, imeAction = ImeAction.Search, onTyping = { typing = it }) { query = it }
412	                    Spacer(Modifier.height(12.dp))
413	                }
414	                LazyColumn(state = channelList, verticalArrangement = Arrangement.spacedBy(2.dp)) {
415	                    itemsIndexed(channels, key = { _, c -> c.id }) { i, ch ->
416	                        LaunchedEffect(ch.id, start) {
417	                            val cached = epg[ch.id]
418	                            // Reload when nothing is cached yet or everything cached has ended.
419	                            if (cached == null || cached.isNotEmpty() && cached.last().end < start + GUIDE_WINDOW) {
420	                                delay(300) // fast scrolling cancels before the request goes out
421	                                epg[ch.id] = runCatching { x.shortEpg(ch, limit = 10) }.getOrDefault(emptyList())
422	                            }
423	                        }
424	                        GuideRow(
425	                            channel = ch,
426	                            programmes = epg[ch.id],
427	                            start = start,
428	                            now = now,
429	                            favorite = ch.id.toString() in favorites,
430	                            onClick = { returnTo = null; playing = i },
431	                            onLongClick = { toggleFavorite(ch) },
432	                            modifier = (if (i == returnTo) Modifier.focusRequester(channelFocus) else Modifier)
433	                                .onPreviewKeyEvent { e ->
434	                                    // Right on a catch-up channel opens its recordings.
435	                                    if (ch.archiveDays > 0 && e.key == Key.DirectionRight && e.type == KeyEventType.KeyDown) { archiveOf = ch; true } else false
436	                                },
437	                        )
438	                    }
439	                }
440	            }
441	        }
442	        playing?.let { start ->
443	            Player(
444	                x, channels, start,
445	                onChannel = { lastPrefs.edit().putString("category", selected).putInt("channel", it.id).apply() },
446	                onWatched = { ch ->
447	                    // Saved right away, shown on exit: reordering the list under the player would shift returnTo.
448	                    val ids = (listOf(ch.id) + readRecent().filter { it != ch.id }).take(10)
449	                    lastPrefs.edit().putString("recent", ids.joinToString(",")).apply()
450	                },
451	                onStartOver = { ch, p ->
452	                    x.archiveUrl(ch, p)?.let {
453	                        replay = Playback(it, "${ch.label} · ${p.title}", "archive", ch.logo)
454	                        liveAfter = ch; backToLive = true; playing = null
455	                    }
456	                },
457	                onExit = { last ->
458	                    val id = channels.getOrNull(last)?.id
459	                    recent = readRecent()
460	                    playing = null
461	                    returnTo = channelsOf(selected, closed).indexOfFirst { it.id == id }.takeIf { it >= 0 } ?: last
462	                },
463	            )
464	        }
465	        archiveOf?.let { ch ->
466	            ArchivePanel(
467	                x, ch, active = replay == null,
468	                onPlay = { p ->
469	                    x.archiveUrl(ch, p)?.let { replay = Playback(it, "${ch.label} · ${p.title}", "archive", ch.logo) }
470	                    liveAfter = ch.takeIf { p.end > System.currentTimeMillis() }
471	                },
472	                onClose = { archiveOf = null; returnTo = channels.indexOf(ch).takeIf { it >= 0 }; refocus++ },
473	                modifier = Modifier.align(Alignment.CenterEnd),
474	            )
475	        }
476	        fun goLive(ch: Channel?) {
477	            val i = ch?.let { channels.indexOf(it) } ?: -1
478	            if (i >= 0) { archiveOf = null; returnTo = null; playing = i }
479	        }
480	        replay?.let { p ->
481	            key(p.url) {
482	                VodPlayer(
483	                    p, store = null,
484	                    // The recording of a running programme ends at "now": carry on live.
485	                    onEnded = { replay = null; goLive(liveAfter); liveAfter = null; backToLive = false },
486	                    onExit = { replay = null; if (backToLive) goLive(liveAfter); liveAfter = null; backToLive = false },
487	                )
488	            }
489	        }
490	        menu?.let { cat ->
491	            val isLocked = lock.isLocked("live", cat)
492	            CategoryMenu(
493	                cat.label, isLocked, hidden = cat.id in hidden,
494	                onToggleHidden = { toggleHidden(cat); menu = null },
495	                onToggleLock = {
496	                    menu = null
497	                    // Locking needs a PIN to exist; unlocking needs the PIN unless the session is already open.
498	                    val action = { lock.setLocked("live", cat, !isLocked) }
499	                    if (lock.pin == null || isLocked && !Session.open) gate = action else action()
500	                },
501	                onClose = { menu = null },
502	            )
503	        }
504	        gate?.let { action -> PinGate(lock, onOk = { action(); gate = null }, onCancel = { gate = null }) }
505	    }
506	}
507	
508	private const val FAVORITES = "__favorites"
509	private const val RECENT = "__recent"
510	private const val SEARCH = "__search"
511	private const val TOGGLE_HIDDEN = "__toggle_hidden"
512	
513	/** Small outlined tag, e.g. a country prefix or quality. */
514	@Composable
515	fun Badge(text: String, modifier: Modifier = Modifier) {
516	    Text(
517	        text,
518	        modifier
519	            .border(1.dp, LocalContentColor.current.copy(alpha = 0.4f), RoundedCornerShape(4.dp))
520	            .padding(horizontal = 5.dp, vertical = 1.dp),
521	        style = MaterialTheme.typography.labelSmall,
522	        color = LocalContentColor.current.copy(alpha = 0.7f),
523	    )
524	}
525	
526	@Composable
527	fun Logo(ch: Channel, size: Int = 40) {
528	    Box(Modifier.size(size.dp).clip(RoundedCornerShape(6.dp)), contentAlignment = Alignment.Center) {
529	        if (ch.logo != null) AsyncImage(model = ch.logo, contentDescription = null, modifier = Modifier.fillMaxSize())
530	        else Text(ch.num.toString(), style = MaterialTheme.typography.labelSmall)
531	    }
532	}
