package io.github.thiemotorres.huru

import androidx.activity.compose.BackHandler
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.FocusRequester
import androidx.compose.ui.focus.focusRequester
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.platform.LocalFocusManager
import androidx.compose.ui.platform.LocalSoftwareKeyboardController
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.tv.material3.*
import kotlinx.coroutines.android.awaitFrame
import kotlinx.coroutines.launch

/** Focus target for the "add source" button. */
const val ADD_SOURCE = "__add_source"
private const val PIN_BUTTON = "__pin"

/** Settings: manage sources (switch, edit, delete, add) next to the about panel. */
@Composable
fun SettingsScreen(
    header: @Composable () -> Unit,
    sources: List<Account>,
    active: Account,
    focusId: String?,
    onFocusId: (String?) -> Unit,
    onActivate: (Account) -> Unit,
    onSave: (Account) -> Unit,
    onDelete: (Account) -> Unit,
) {
    val context = LocalContext.current
    var form by remember { mutableStateOf<Account?>(null) } // source being edited
    var adding by remember { mutableStateOf(false) }
    val lock = remember(active) { Lock(context, active) }
    var pinAction by remember { mutableStateOf<String?>(null) } // "change" or "remove"
    pinAction?.let { action ->
        PinGate(
            lock, change = action == "change",
            onOk = { if (action == "remove") lock.savePin(null); pinAction = null; onFocusId(PIN_BUTTON) },
            onCancel = { pinAction = null; onFocusId(PIN_BUTTON) },
        )
        return
    }
    if (adding || form != null) {
        SourceForm(
            initial = form,
            onSave = { onSave(it); form = null; adding = false },
            onCancel = { onFocusId(form?.id ?: ADD_SOURCE); form = null; adding = false },
        )
        return
    }
    // Focus the row we came from (saved, edited, neighbour of a deleted one) instead of the mode switch.
    val requesters = remember { mutableMapOf<String, FocusRequester>() }
    fun requester(id: String) = requesters.getOrPut(id) { FocusRequester() }
    LaunchedEffect(focusId) {
        val id = focusId ?: return@LaunchedEffect
        awaitFrame()
        runCatching { requester(id).requestFocus() }
        onFocusId(null)
    }
    Column(Modifier.fillMaxSize().padding(24.dp)) {
        header()
        Row(Modifier.fillMaxSize().padding(top = 24.dp), horizontalArrangement = Arrangement.spacedBy(48.dp)) {
            Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(stringResource(R.string.sources_title), style = MaterialTheme.typography.titleLarge)
                LazyColumn(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    items(sources, key = { it.id }) { source ->
                        SourceRow(source, source == active, Modifier.focusRequester(requester(source.id)), onActivate, { form = it }, onDelete)
                    }
                    item {
                        Button(onClick = { adding = true }, Modifier.padding(top = 8.dp).focusRequester(requester(ADD_SOURCE))) {
                            Text(stringResource(R.string.source_add))
                        }
                    }
                    item {
                        Column(Modifier.padding(top = 32.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(stringResource(R.string.parental_title), style = MaterialTheme.typography.titleLarge)
                            Text(stringResource(R.string.parental_hint), color = Color.White.copy(alpha = 0.7f))
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                OutlinedButton(onClick = { pinAction = "change" }, Modifier.focusRequester(requester(PIN_BUTTON))) {
                                    Text(stringResource(if (lock.pin == null) R.string.pin_set else R.string.pin_change))
                                }
                                if (lock.pin != null) OutlinedButton(onClick = { pinAction = "remove" }) { Text(stringResource(R.string.pin_remove)) }
                            }
                        }
                    }
                    item {
                        val prefs = displayPrefs(context)
                        var flags by remember { mutableStateOf(prefs.getBoolean("flags", false)) }
                        Column(Modifier.padding(top = 32.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(stringResource(R.string.display_title), style = MaterialTheme.typography.titleLarge)
                            ListItem(
                                selected = false,
                                onClick = { flags = !flags; prefs.edit().putBoolean("flags", flags).apply() },
                                headlineContent = { Text(stringResource(R.string.display_flags)) },
                                trailingContent = { Switch(checked = flags, onCheckedChange = null) },
                            )
                        }
                    }
                }
            }
            AboutPanel(Modifier.width(380.dp))
        }
    }
}

@Composable
private fun SourceRow(
    source: Account,
    active: Boolean,
    focus: Modifier,
    onActivate: (Account) -> Unit,
    onEdit: (Account) -> Unit,
    onDelete: (Account) -> Unit,
) {
    var confirm by remember { mutableStateOf(false) }
    // Asked fresh each time: renewing an account moves the date. No date if unlimited or unreachable.
    val expiry by produceState<Long?>(null, source) {
        if (source.type == XTREAM) value = runCatching { Xtream(source).login() }.getOrNull() // M3U knows no expiry
    }
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        ListItem(
            selected = active,
            onClick = { onActivate(source) },
            headlineContent = { Text(source.name.ifBlank { hostOf(source.server) }, maxLines = 1, overflow = TextOverflow.Ellipsis) },
            supportingContent = {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    val detail = if (source.type == M3U) stringResource(R.string.source_type_m3u) else source.user
                    Text("${hostOf(source.server)} · $detail", Modifier.weight(1f, fill = false), maxLines = 1, overflow = TextOverflow.Ellipsis)
                    expiry?.let {
                        val date = java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM).format(java.util.Date(it))
                        val expired = it < System.currentTimeMillis()
                        Text(
                            "· " + stringResource(if (expired) R.string.source_expired else R.string.source_expires, date),
                            color = if (expired) MaterialTheme.colorScheme.error else Color.Unspecified, maxLines = 1,
                        )
                    }
                }
            },
            trailingContent = if (active) { { Badge(stringResource(R.string.source_active)) } } else null,
            modifier = Modifier.weight(1f).then(focus),
        )
        OutlinedButton(onClick = { onEdit(source) }) { Text(stringResource(R.string.source_edit)) }
        OutlinedButton(onClick = { if (confirm) onDelete(source) else confirm = true }) {
            Text(stringResource(if (confirm) R.string.source_delete_confirm else R.string.source_delete))
        }
    }
}

/**
 * Add or edit a source. Validates the login before saving. Without [onCancel] it is the first-run setup,
 * which also offers the public demo server.
 */
@Composable
fun SourceForm(initial: Account?, onSave: (Account) -> Unit, onCancel: (() -> Unit)?) {
    var name by remember { mutableStateOf(initial?.name.orEmpty()) }
    var server by remember { mutableStateOf(initial?.server.orEmpty()) }
    var user by remember { mutableStateOf(initial?.user.orEmpty()) }
    var pass by remember { mutableStateOf(initial?.pass.orEmpty()) }
    var type by remember { mutableStateOf(initial?.type ?: XTREAM) }
    var epg by remember { mutableStateOf(initial?.epg.orEmpty()) }
    var busy by remember { mutableStateOf(false) }
    var error by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    val keyboard = LocalSoftwareKeyboardController.current
    val focusManager = LocalFocusManager.current
    val loginFailed = stringResource(R.string.login_failed, "%s")
    val connectionFailed = stringResource(R.string.connection_failed)
    val first = remember { FocusRequester() }
    LaunchedEffect(Unit) { awaitFrame(); runCatching { first.requestFocus() } }
    BackHandler(enabled = onCancel != null) { onCancel?.invoke() }

    fun submit(candidate: Account) {
        busy = true; error = null
        scope.launch {
            runCatching { provider(candidate).login() }
                .onSuccess {
                    // Otherwise the IME session stays open and Fire OS re-shows the keyboard over the player.
                    keyboard?.hide()
                    focusManager.clearFocus(force = true)
                    onSave(candidate)
                }
                .onFailure { error = it.message?.let { m -> loginFailed.format(m) } ?: connectionFailed; busy = false }
        }
    }

    Column(
        Modifier.fillMaxSize().padding(horizontal = 48.dp, vertical = 24.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp, Alignment.CenterVertically),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            stringResource(when { onCancel == null -> R.string.setup_welcome; initial == null -> R.string.source_add_title; else -> R.string.source_edit_title }),
            style = MaterialTheme.typography.headlineMedium,
        )
        if (onCancel == null) Text(stringResource(R.string.setup_hint), color = Color.White.copy(alpha = 0.7f))
        Box(Modifier.focusRequester(first)) { Field(stringResource(R.string.source_name), name) { name = it } }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            listOf(XTREAM to R.string.source_type_xtream, M3U to R.string.source_type_m3u).forEach { (t, label) ->
                // Same component for both states: swapping it would drop the focus into the name field.
                OutlinedButton(onClick = { type = t; error = null }) { Text((if (t == type) "✓ " else "") + stringResource(label)) }
            }
        }
        if (type == M3U) {
            Field(stringResource(R.string.login_playlist), server, KeyboardType.Uri) { server = it }
            Field(stringResource(R.string.login_epg), epg, KeyboardType.Uri) { epg = it }
        } else {
            Field(stringResource(R.string.login_server), server, KeyboardType.Uri) { server = it }
            Field(stringResource(R.string.login_user), user) { user = it }
            Field(stringResource(R.string.login_password), pass, KeyboardType.Password, password = true) { pass = it }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.padding(top = 6.dp)) {
            Button(enabled = !busy && server.isNotBlank(), onClick = {
                val base = Account(server.trim(), "", "", id = initial?.id ?: newSourceId(), name = name.trim().ifBlank { hostOf(server) }, type = type)
                submit(if (type == M3U) base.copy(epg = epg.trim()) else base.copy(user = user.trim(), pass = pass))
            }) { Text(stringResource(if (busy) R.string.login_connecting else if (initial == null) R.string.login_submit else R.string.source_save)) }
            if (initial == null) {
                OutlinedButton(enabled = !busy, onClick = { submit(DEMO_SOURCE.copy(id = newSourceId())) }) { Text(stringResource(R.string.try_demo)) }
            }
            if (onCancel != null) OutlinedButton(onClick = onCancel) { Text(stringResource(R.string.cancel)) }
        }
        error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
    }
}

package io.github.thiemotorres.huru

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import org.xml.sax.Attributes
import org.xml.sax.helpers.DefaultHandler
import java.io.BufferedInputStream
import java.io.File
import java.io.IOException
import java.io.InputStream
import java.net.HttpURLConnection
import java.net.URL
import java.text.SimpleDateFormat
import java.util.Locale
import java.util.TimeZone
import java.util.zip.GZIPInputStream
import javax.xml.parsers.SAXParserFactory

/** A parsed playlist: channels in playlist order and the EPG address from its header (url-tvg / x-tvg-url). */
data class Playlist(val channels: List<Channel>, val epgUrl: String?)

private val ATTRIBUTE = Regex("""([\w-]+)="([^"]*)"""")

/**
 * M3U/M3U8 playlist: `#EXTINF:-1 tvg-id=".." tvg-logo=".." group-title="..",Name` followed by the stream URL.
 * Channel ids come from the URL so favourites survive a reordered playlist (unique: lists are keyed by id);
 * categories are the group titles.
 */
fun parseM3u(text: String): Playlist {
    var epgUrl: String? = null
    val channels = mutableListOf<Channel>()
    val ids = HashSet<Int>()
    var info: String? = null
    text.lineSequence().map { it.trim() }.filter { it.isNotEmpty() }.forEach { line ->
        when {
            line.startsWith("#EXTM3U") -> attributes(line).let { epgUrl = it["url-tvg"] ?: it["x-tvg-url"] }
            line.startsWith("#EXTINF") -> info = line
            line.startsWith("#") -> Unit // #EXTVLCOPT, #EXTGRP, …
            else -> {
                val attrs = info?.let(::attributes).orEmpty()
                // The name follows the last comma outside the attribute quotes.
                val name = info?.replace(ATTRIBUTE, "")?.substringAfter(',', "")?.trim().orEmpty()
                    .ifEmpty { attrs["tvg-name"] ?: line.substringAfterLast('/') }
                var id = line.hashCode()
                while (!ids.add(id)) id++ // duplicate entry or hash collision
                channels += Channel(
                    id = id,
                    num = attrs["tvg-chno"]?.toIntOrNull() ?: (channels.size + 1),
                    name = name,
                    logo = attrs["tvg-logo"]?.ifBlank { null },
                    categoryId = attrs["group-title"]?.ifBlank { null } ?: "",
                    url = line,
                    epgId = attrs["tvg-id"]?.ifBlank { null } ?: attrs["tvg-name"]?.ifBlank { null },
                )
                info = null
            }
        }
    }
    return Playlist(channels, epgUrl?.split(',')?.firstOrNull()?.trim()?.ifBlank { null })
}

private fun attributes(line: String) = ATTRIBUTE.findAll(line).associate { it.groupValues[1] to it.groupValues[2] }

/**
 * XMLTV programmes of the channels in [ids] that overlap [from, to), by channel id and sorted.
 * Streamed with SAX: EPG files of 100 MB and more never sit in memory as a whole.
 */
fun parseXmltv(input: InputStream, ids: Set<String>, from: Long, to: Long): Map<String, List<Programme>> {
    val result = HashMap<String, MutableList<Programme>>()
    val handler = object : DefaultHandler() {
        var channel: String? = null
        var start = 0L
        var end = 0L
        var title: StringBuilder? = null
        var inTitle = false // only the first <title> counts (others are translations)

        override fun startElement(uri: String?, local: String?, qName: String, attrs: Attributes) {
            when (qName) {
                "programme" -> {
                    channel = attrs.getValue("channel")?.takeIf { it in ids }
                    start = xmltvTime(attrs.getValue("start"))
                    end = xmltvTime(attrs.getValue("stop"))
                    title = null
                }
                "title" -> if (channel != null && title == null) { title = StringBuilder(); inTitle = true }
            }
        }

        override fun characters(ch: CharArray, offset: Int, length: Int) { if (inTitle) title?.append(ch, offset, length) }

        override fun endElement(uri: String?, local: String?, qName: String) {
            when (qName) {
                "title" -> inTitle = false
                "programme" -> {
                    val id = channel
                    if (id != null && end > from && start < to && start > 0) {
                        result.getOrPut(id) { mutableListOf() } += Programme(title?.toString()?.trim().orEmpty(), start, end)
                    }
                    channel = null; title = null
                }
            }
        }
    }
    SAXParserFactory.newInstance().newSAXParser().parse(input, handler)
    return result.mapValues { (_, list) -> list.sortedBy { it.start } }
}

/** "20261112183000 +0100" → epoch ms; without an offset the time is taken as UTC. 0 if unreadable. */
fun xmltvTime(value: String?): Long {
    val v = value?.trim() ?: return 0
    return runCatching {
        if (' ' in v) SimpleDateFormat("yyyyMMddHHmmss Z", Locale.US).parse(v)!!.time
        else SimpleDateFormat("yyyyMMddHHmmss", Locale.US).apply { timeZone = TimeZone.getTimeZone("UTC") }.parse(v.take(14))!!.time
    }.getOrDefault(0)
}

/** gzip is recognised by its magic bytes, not the file name (many EPG URLs hide it). */
private fun maybeGzip(input: InputStream): InputStream {
    val buffered = BufferedInputStream(input)
    buffered.mark(2)
    val gzip = buffered.read() == 0x1f && buffered.read() == 0x8b
    buffered.reset()
    return if (gzip) GZIPInputStream(buffered) else buffered
}

private fun open(url: String): HttpURLConnection =
    (URL(url.trim()).openConnection() as HttpURLConnection).apply {
        connectTimeout = 10_000
        readTimeout = 60_000
        if (responseCode != 200) { disconnect(); throw IOException("Server responded with HTTP $responseCode") }
    }

/** M3U source: live channels only; the guide comes from XMLTV (the playlist's own or the one entered). */
class M3u(override val account: Account) : Provider {
    @Volatile private var channels: List<Channel> = emptyList()
    @Volatile private var headerEpg: String? = null
    private var guide: Map<String, List<Programme>>? = null
    private val guideLock = Mutex()

    private suspend fun download(): String = withContext(Dispatchers.IO) {
        val conn = open(account.server)
        try { maybeGzip(conn.inputStream).bufferedReader().use { it.readText() } } finally { conn.disconnect() }
    }

    override suspend fun login(): Long? {
        if (withContext(Dispatchers.Default) { parseM3u(download()) }.channels.isEmpty()) throw IOException("No channels in the playlist")
        return null
    }

    override suspend fun loadLive(cacheDir: File, show: suspend (List<Category>, List<Channel>) -> Unit) =
        cachedLists(cacheDir, account, listOf("playlist"), { download() }) { (text) ->
            val playlist = withContext(Dispatchers.Default) { parseM3u(text) }
            channels = playlist.channels
            headerEpg = playlist.epgUrl
            // Groups in playlist order; channels without a group collect under the source's name.
            val other = account.name.ifBlank { hostOf(account.server) }
            show(playlist.channels.map { it.categoryId }.distinct().map { Category(it, it.ifEmpty { other }) }, playlist.channels)
        }

    // ponytail: the XMLTV file is downloaded once per app start and kept for 24 h ahead in memory;
    // cache the trimmed guide on disk if big EPG files make the first rows slow.
    override suspend fun shortEpg(channel: Channel, limit: Int): List<Programme> {
        val id = channel.epgId ?: return emptyList()
        val all = guideLock.withLock { guide ?: loadGuide().also { guide = it } }
        return upcoming(all[id].orEmpty(), System.currentTimeMillis(), limit)
    }

    private suspend fun loadGuide(): Map<String, List<Programme>> {
        val url = account.epg.ifBlank { null } ?: headerEpg ?: return emptyMap()
        val ids = channels.mapNotNull { it.epgId }.toSet()
        val now = System.currentTimeMillis()
        return withContext(Dispatchers.IO) {
            runCatching {
                val conn = open(url)
                try { maybeGzip(conn.inputStream).use { parseXmltv(it, ids, now - 3_600_000, now + 86_400_000) } } finally { conn.disconnect() }
            }.getOrDefault(emptyMap()) // no guide is no reason to fail the channel list
        }
    }

    override fun streamUrl(channel: Channel) = channel.url ?: ""
}

