                }
            }
        }
        playing?.let { start ->
            Player(
                x, channels, start,
                onChannel = { lastPrefs.edit().putString("category", selected).putInt("channel", it.id).apply() },
                onWatched = { ch ->
                    // Saved right away, shown on exit: reordering the list under the player would shift returnTo.
                    val ids = (listOf(ch.id) + readRecent().filter { it != ch.id }).take(10)
                    lastPrefs.edit().putString("recent", ids.joinToString(",")).apply()
                },
                onStartOver = { ch, p ->
                    x.archiveUrl(ch, p)?.let {
                        replay = Playback(it, "${ch.label} · ${p.title}", "archive", ch.logo)
                        liveAfter = ch; backToLive = true; playing = null
                    }
                },
                onExit = { last ->
                    val id = channels.getOrNull(last)?.id
                    recent = readRecent()
                    playing = null
                    returnTo = channelsOf(selected, closed).indexOfFirst { it.id == id }.takeIf { it >= 0 } ?: last
                },
            )
        }
        archiveOf?.let { ch ->
            ArchivePanel(
                x, ch, active = replay == null,
                onPlay = { p ->
                    x.archiveUrl(ch, p)?.let { replay = Playback(it, "${ch.label} · ${p.title}", "archive", ch.logo) }
                    liveAfter = ch.takeIf { p.end > System.currentTimeMillis() }
                },
                onClose = { archiveOf = null; returnTo = channels.indexOf(ch).takeIf { it >= 0 }; refocus++ },
                modifier = Modifier.align(Alignment.CenterEnd),
            )
        }
        fun goLive(ch: Channel?) {
            val i = ch?.let { channels.indexOf(it) } ?: -1
            if (i >= 0) { archiveOf = null; returnTo = null; playing = i }
        }
        replay?.let { p ->
            key(p.url) {
                VodPlayer(
                    p, store = null,
                    // The recording of a running programme ends at "now": carry on live.
                    onEnded = { replay = null; goLive(liveAfter); liveAfter = null; backToLive = false },
                    onExit = { replay = null; if (backToLive) goLive(liveAfter); liveAfter = null; backToLive = false },
                )
            }
        }
        menu?.let { cat ->
            val isLocked = lock.isLocked("live", cat)
            CategoryMenu(
                cat.label, isLocked, hidden = cat.id in hidden,
                onToggleHidden = { toggleHidden(cat); menu = null },
                onToggleLock = {
                    menu = null
                    // Locking needs a PIN to exist; unlocking needs the PIN unless the session is already open.
                    val action = { lock.setLocked("live", cat, !isLocked) }
                    if (lock.pin == null || isLocked && !Session.open) gate = action else action()
                    )
                }
            }
        }
    }
}

/** Player for movies and episodes: OK pauses, Left/Right seeks, the position is remembered. */
/** [store] null: nothing is remembered (catch-up recordings expire anyway). */
@Composable
fun VodPlayer(playback: Playback, store: ProgressStore?, onEnded: () -> Unit, onExit: () -> Unit) {
    val context = LocalContext.current
    val keyboard = LocalSoftwareKeyboardController.current
    LaunchedEffect(Unit) { keyboard?.hide() } // an open search keyboard would otherwise pop up over the video
    var error by remember { mutableStateOf<String?>(null) }
    var buffering by remember { mutableStateOf(true) }
    var paused by remember { mutableStateOf(false) }
    var position by remember { mutableLongStateOf(0L) }
    var length by remember { mutableLongStateOf(0L) }
    var overlayTick by remember { mutableIntStateOf(0) }
    var overlay by remember { mutableStateOf(true) }
    var menu by remember { mutableStateOf(false) }

    val scope = rememberCoroutineScope()
    val reconnect = remember { Reconnect(scope) }
    lateinit var player: ExoPlayer
    fun save() = store?.save(playback, player.currentPosition, player.duration)
    player = remember {
        newPlayer(context).build().apply {
            setMediaItem(MediaItem.fromUri(playback.url))
            seekTo(store?.position(playback.resumeKey) ?: 0)
            prepare()
            playWhenReady = true
            addListener(object : MediaPlayer.Listener {
                // prepare() after an error continues at the current position.
                override fun onPlayerError(e: PlaybackException) { if (!reconnect.retry { prepare() }) error = describe(e) }
                override fun onPlaybackStateChanged(state: Int) {
                    buffering = state == MediaPlayer.STATE_BUFFERING
                    if (state == MediaPlayer.STATE_READY) reconnect.reset()
                    if (state == MediaPlayer.STATE_ENDED) { save(); onEnded() }
                }
            })
        }
    }
    DisposableEffect(Unit) { onDispose { save(); player.release() } }
    LaunchedEffect(Unit) {
        var ticks = 0
        while (true) {
            position = player.currentPosition
            length = player.duration.coerceAtLeast(0)
            if (++ticks % 20 == 0) save() // every 10 s in case the app gets killed
            delay(500)
        }
    }
    LaunchedEffect(overlayTick) { overlay = true; delay(4_000); overlay = false }

    val focus = remember { FocusRequester() }
    LaunchedEffect(Unit) { focus.requestFocus() }
    BackHandler(onBack = onExit)

    fun seekBy(ms: Long) {
        player.seekTo((player.currentPosition + ms).coerceIn(0, length.takeIf { it > 0 } ?: Long.MAX_VALUE))
        position = player.currentPosition
        overlayTick++
    }

    Box(
        Modifier
            .fillMaxSize()
            .background(Color.Black)
            .onKeyEvent { e ->
                if (e.type != KeyEventType.KeyDown || menu) return@onKeyEvent false
                when (e.key) {
                    Key.Menu -> { menu = true; true }
                    Key.DirectionCenter, Key.Enter, Key.MediaPlayPause, Key.MediaPlay, Key.MediaPause -> {
                        if (error != null) { error = null; reconnect.reset(); player.prepare() }
                        player.playWhenReady = !player.playWhenReady
                        paused = !player.playWhenReady
                        overlayTick++
                        true
                    }
                    Key.DirectionLeft, Key.MediaRewind -> { seekBy(-10_000); true }
                    Key.DirectionRight, Key.MediaFastForward -> { seekBy(30_000); true }
                    Key.DirectionUp, Key.DirectionDown -> { overlayTick++; true }
                    else -> false
                }
            }
            .focusRequester(focus)
            .focusable(),
    ) {
        VideoSurface(player, onExit)
        if (buffering && error == null) {
            Text(stringResource(R.string.loading), Modifier.align(Alignment.Center), color = Color.White.copy(alpha = 0.7f))
        }
        AnimatedVisibility(
            visible = overlay || paused || error != null,
            enter = fadeIn(), exit = fadeOut(),
            modifier = Modifier.align(Alignment.BottomCenter),
        ) {
            Column(
                Modifier
                    .fillMaxWidth()
                    .background(Brush.verticalGradient(listOf(Color.Transparent, Color.Black.copy(alpha = 0.9f))))
                    .padding(horizontal = 48.dp, vertical = 32.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Text((if (paused) "❚❚  " else "") + playback.title, style = MaterialTheme.typography.headlineSmall, color = Color.White)
                error?.let { Text(stringResource(R.string.playback_error, it), color = MaterialTheme.colorScheme.error) }
                val progress = if (length > 0) (position.toFloat() / length).coerceIn(0f, 1f) else 0f
                Box(Modifier.fillMaxWidth().height(4.dp).background(Color.White.copy(alpha = 0.2f))) {
                    Box(Modifier.fillMaxWidth(progress).fillMaxHeight().background(Accent))
                }
                Text(
                    "${duration(position)} / ${duration(length)}   ·   ◀ 10 s   ▶ 30 s   ·   " + stringResource(R.string.tracks_hint),
                    style = MaterialTheme.typography.bodySmall,
                    color = Color.White.copy(alpha = 0.7f),
                )
            }
        }
        if (menu) TrackMenu(player, { menu = false; focus.requestFocus() }, Modifier.align(Alignment.CenterEnd))
    }
}

/** 3725000 → "1:02:05", 65000 → "1:05". */
fun duration(ms: Long): String {
    val s = ms / 1000
    return if (s >= 3600) "%d:%02d:%02d".format(s / 3600, s / 60 % 60, s % 60) else "%d:%02d".format(s / 60, s % 60)
}

/** What the live TV screens need from a source. Catch-up, movies and series exist only for Xtream. */
interface Provider {
    val account: Account
    /** Checks the source; returns the account's expiry (epoch ms) if known. Throws if it is unusable. */
    suspend fun login(): Long?
    /** Categories and channels: the cached state first (if any), then the fresh one; server errors are thrown. */
    suspend fun loadLive(cacheDir: File, show: suspend (List<Category>, List<Channel>) -> Unit)
    /** The running programme and the next ones. */
    suspend fun shortEpg(channel: Channel, limit: Int = 2): List<Programme>
    fun streamUrl(channel: Channel): String
    /** A live stream failed: true if the provider switched to something worth retrying. */
    fun liveFallback(): Boolean = false
    suspend fun archive(channel: Channel, now: Long = System.currentTimeMillis()): List<Programme> = emptyList()
    fun archiveUrl(channel: Channel, p: Programme): String? = null
}

fun provider(account: Account): Provider = if (account.type == M3U) M3u(account) else Xtream(account)
data class Category(val id: String, val name: String) {
    private val match = COUNTRY_PREFIX.matchEntire(name)
        ?: SPACED_PREFIX.matchEntire(name)?.takeIf { it.groupValues[1] in COUNTRY_CODES }
    /** Country prefix from "PT | Desporto", "BR: Abertos" or "DE MAGENTA TV" (known codes only) → "PT". */
    val prefix: String? = match?.groupValues?.get(1)
    val label: String = match?.groupValues?.get(2) ?: name
}

/**
 * archiveDays > 0: the provider keeps recordings (catch-up) for that many days.
 * [url] and [epgId] only for M3U channels (the stream address and the XMLTV channel id).
 */
data class Channel(
    val id: Int, val num: Int, val name: String, val logo: String?, val categoryId: String, val archiveDays: Int = 0,
    val url: String? = null, val epgId: String? = null,
) {
    /** Quality suffix at the end of the name: "SPORT TV 1 FHD" → "FHD". */
    val quality: String? = QUALITY_SUFFIX.find(name)?.groupValues?.get(1)?.uppercase()
    val label: String = name.replace(QUALITY_SUFFIX, "").trim().ifEmpty { name }
}

private val COUNTRY_PREFIX = Regex("""^\s*([A-Z]{2,3})\s*[|:]\s*(.+?)\s*$""")
private val SPACED_PREFIX = Regex("""^\s*([A-Z]{2})\s+(.+?)\s*$""")
// Without a separator only real country codes count ("THE BEST" stays whole); TV (Tuvalu) is too ambiguous.
private val COUNTRY_CODES = java.util.Locale.getISOCountries().toSet() + setOf("UK", "EN") - "TV"

/** Prefix → flag emoji ("DE" → 🇩🇪, UK/EN → 🇬🇧); null for codes that are no country ("EXYU"). */
fun flagOf(code: String): String? {
    val country = when (code) { "UK", "EN" -> "GB"; else -> code }
    if (country.length != 2 || country !in COUNTRY_CODES) return null
    return country.map { String(Character.toChars(0x1F1E6 + (it - 'A'))) }.joinToString("")
}
private val QUALITY_SUFFIX = Regex("""\s+[\[(]?(UHD|4K|FHD|HD|SD|LOW|HEVC)[\])]?\s*$""", RegexOption.IGNORE_CASE)
/** [serverStart] is the panel's own start text, needed verbatim for catch-up URLs. */
data class Programme(val title: String, val start: Long, val end: Long, val serverStart: String? = null)

/** "2026-11-11 23:35:00" → "2026-11-11:23-35", the start format of Xtream timeshift URLs. */
fun archiveTime(serverStart: String): String? =
    fun movieUrl(movie: VodItem) =
        "$base/movie/${Uri.encode(account.user)}/${Uri.encode(account.pass)}/${movie.id}.${movie.ext}"

    fun episodeUrl(episode: Episode) =
        "$base/series/${Uri.encode(account.user)}/${Uri.encode(account.pass)}/${episode.id}.${episode.ext}"

    /**
     * Recorded programmes of a catch-up channel, newest first, including the running one (plays from its start up to now).
     * Not filtered by has_archive: panels set it hours late.
     */
    override suspend fun archive(channel: Channel, now: Long): List<Programme> =
        epg(get("&action=get_simple_data_table&stream_id=${channel.id}"))
            .filter { it.start <= now && it.start >= now - channel.archiveDays * 86_400_000L && it.serverStart != null }
            .sortedByDescending { it.start }

    override fun archiveUrl(channel: Channel, p: Programme): String? {
        val time = p.serverStart?.let(::archiveTime) ?: return null
        val minutes = ((p.end - p.start) / 60_000).coerceAtLeast(1)
        return "$base/timeshift/${Uri.encode(account.user)}/${Uri.encode(account.pass)}/$minutes/$time/${channel.id}.ts"
    }

    /** Live format: MPEG-TS first; switches to HLS for the rest of the session if a TS stream fails. */
    @Volatile private var liveExt = "ts"

    override fun liveFallback(): Boolean = (liveExt == "ts").also { if (it) liveExt = "m3u8" }

    override fun streamUrl(channel: Channel) =
        "$base/live/${Uri.encode(account.user)}/${Uri.encode(account.pass)}/${channel.id}.$liveExt"
}

/** Depending on the panel, "episodes" is an object {"1": [...], "2": [...]} or an array of arrays. */

