    programmes: List<Programme>?, // null = still loading
    start: Long,
    now: Long,
    favorite: Boolean,
    onClick: () -> Unit,
    onLongClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Surface(
        onClick = onClick,
        onLongClick = onLongClick,
        modifier = modifier.fillMaxWidth().height(64.dp),
        shape = ClickableSurfaceDefaults.shape(RoundedCornerShape(8.dp)),
        colors = ClickableSurfaceDefaults.colors(
            containerColor = Color.Transparent,
            contentColor = Color.White,
            focusedContainerColor = Color.White.copy(alpha = 0.08f),
            focusedContentColor = Color.White,
        ),
        scale = ClickableSurfaceDefaults.scale(focusedScale = 1f),
        border = ClickableSurfaceDefaults.border(
            focusedBorder = Border(BorderStroke(2.dp, Accent), shape = RoundedCornerShape(8.dp)),
        ),
    ) {
        Row(Modifier.fillMaxSize().padding(horizontal = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            Row(Modifier.width(NAME_WIDTH), verticalAlignment = Alignment.CenterVertically) {
                Logo(channel)
                Text(
                    channel.label,
                    Modifier.weight(1f, fill = false).padding(start = 12.dp, end = 8.dp),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                channel.quality?.let { Badge(it) }
                if (channel.archiveDays > 0) Text("⟲", Modifier.padding(start = 8.dp), color = Color.White.copy(alpha = 0.6f))
                if (favorite) Text("★", Modifier.padding(horizontal = 8.dp), color = Accent)
            }
            BoxWithConstraints(Modifier.weight(1f).fillMaxHeight().padding(vertical = 8.dp)) {
                val end = start + GUIDE_WINDOW
                val visible = programmes.orEmpty().filter { it.end > start && it.start < end }
                if (programmes != null && visible.isEmpty()) {
                    Text(
                        stringResource(R.string.no_programme),
                        Modifier.align(Alignment.CenterStart).padding(start = 8.dp),
                        color = Color.White.copy(alpha = 0.3f),
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                for (p in visible) {
                    val from = maxOf(p.start, start)
                    val to = minOf(p.end, end)
                    val width = maxWidth * ((to - from).toFloat() / GUIDE_WINDOW)
                    val running = now in p.start until p.end
                    Box(
                        Modifier
                            .offset(x = maxWidth * ((from - start).toFloat() / GUIDE_WINDOW))
                            .width(width)
                            .fillMaxHeight()
                            .padding(horizontal = 1.dp)
                            .clip(RoundedCornerShape(4.dp))
                            .background(if (running) Accent.copy(alpha = 0.15f) else Color.White.copy(alpha = 0.06f)),
                    ) {
                        if (running) { // elapsed part of the current programme
                            Box(
                                Modifier
                                    .fillMaxHeight()
                                    .fillMaxWidth(((now - from).toFloat() / (to - from)).coerceIn(0f, 1f))
                                    .background(Accent.copy(alpha = 0.25f)),
                            )
                        }
                        if (width > 56.dp) {
                            Text(
                                p.title,
                                Modifier.align(Alignment.CenterStart).padding(horizontal = 8.dp),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                style = MaterialTheme.typography.bodySmall,
                            )
                        }
                    }
                }
            }
        }
    }
}

/**
 * Catch-up list of a channel (Right on a ⟲ channel). Traps focus until closed; [active] false while a recording plays
 * on top, then focus comes back to the last picked programme.
 */
@Composable
@OptIn(ExperimentalComposeUiApi::class) // focusProperties exit
fun ArchivePanel(x: Provider, channel: Channel, active: Boolean, onPlay: (Programme) -> Unit, onClose: () -> Unit, modifier: Modifier = Modifier) {
        Row(Modifier.fillMaxSize().padding(24.dp), horizontalArrangement = Arrangement.spacedBy(24.dp)) {
            Column(Modifier.width(260.dp)) {
                header()
                Spacer(Modifier.height(12.dp))
                LazyColumn(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    itemsIndexed(cats, key = { _, c -> c.id }) { i, cat ->
                        val special = cat.id == SEARCH || cat.id == FAVORITES || cat.id == RECENT || cat.id == TOGGLE_HIDDEN
                        CategoryItem(
                            cat,
                            selected = cat.id == selected,
                            dim = cat.id in hidden || cat.id == TOGGLE_HIDDEN,
                            locked = !special && lock.isLocked("live", cat),
                            onClick = {
                                if (cat.id == TOGGLE_HIDDEN) showHidden = !showHidden
                                else if (cat.id in closed) { focusCat = cat.id; gate = {} }
                            },
                            onLongClick = { if (!special) { focusCat = cat.id; menu = cat } },
                            modifier = Modifier
                                // Start on the selected category (not on Search at the top).
                                .then(if (cat.id == selected || selected == null && i == 0) Modifier.focusRequester(firstCategory) else Modifier)
                                .then(if (cat.id == focusCat) Modifier.focusRequester(catFocus) else Modifier)
                                .onFocusChanged { if (it.isFocused && cat.id != TOGGLE_HIDDEN && !typing) selected = cat.id },
                        )
                    }
                }
            }
            val now = rememberNow()
            val start = guideStart(now)
            Column(Modifier.weight(1f)) {
                GuideHeader(start, now)
                if (selected in closed) LockedHint()
                if (selected == SEARCH) {
                    Field(stringResource(R.string.search_hint_channels), query, imeAction = ImeAction.Search, onTyping = { typing = it }) { query = it }
                    Spacer(Modifier.height(12.dp))
                }
                LazyColumn(state = channelList, verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    itemsIndexed(channels, key = { _, c -> c.id }) { i, ch ->
                        LaunchedEffect(ch.id, start) {
                            val cached = epg[ch.id]
                            // Reload when nothing is cached yet or everything cached has ended.
                            if (cached == null || cached.isNotEmpty() && cached.last().end < start + GUIDE_WINDOW) {
                                delay(300) // fast scrolling cancels before the request goes out
                                epg[ch.id] = runCatching { x.shortEpg(ch, limit = 10) }.getOrDefault(emptyList())
                            }
                        }
                        GuideRow(
                            channel = ch,
                            programmes = epg[ch.id],
                            start = start,
                            now = now,
                            favorite = ch.id.toString() in favorites,
                            onClick = { returnTo = null; playing = i },
                            onLongClick = { toggleFavorite(ch) },
                            modifier = (if (i == returnTo) Modifier.focusRequester(channelFocus) else Modifier)
                                .onPreviewKeyEvent { e ->
                                    // Right on a catch-up channel opens its recordings.
                                    if (ch.archiveDays > 0 && e.key == Key.DirectionRight && e.type == KeyEventType.KeyDown) { archiveOf = ch; true } else false
                                },
                        )
                    }
                }

