 * The start is shifted within the panel's own clock text, so the server's time zone does not matter.
 */
fun resumeFrom(channel: Channel, epg: List<Programme>, pausedAt: Long, now: Long): Programme? {
    if (channel.archiveDays <= 0) return null
    val p = epg.firstOrNull { pausedAt in it.start until it.end } ?: return null
