content.content:
    val firstCategory = remember { FocusRequester() }
    val catFocus = remember { FocusRequester() }
    LaunchedEffect(menu == null && gate == null) {
        if (menu == null && gate == null && focusCat != null) { awaitFrame(); runCatching { catFocus.requestFocus() } }
    }
    val channelFocus = remember { FocusRequester() }
    val channelList = rememberLazyListState()
    val scope = rememberCoroutineScope()

    LaunchedEffect(Unit) { awaitFrame(); if (autoFocus && playing == null) runCatching { firstCategory.requestFocus() } }
    LaunchedEffect(returnTo, refocus) {
        val i = returnTo ?: return@LaunchedEffect
        channelList.scrollToItem(i)
        awaitFrame()
        runCatching { channelFocus.requestFocus() }
    }

    // ponytail: reminders only show while live TV is open (not in Movies/Series or with the app closed);
    // an AlarmManager notification would cover those.
    LaunchedEffect(reminders, playing) {
        while (true) {
            val now = System.currentTimeMillis()
            val watching = if (playing != null) lastPrefs.getInt("channel", -1) else null
            reminders.firstOrNull { it.channelId == watching && now >= it.start - 120_000 }?.let { saveReminders(reminders - it) }
            due = reminders.filter { now in it.start - 120_000..it.start + 15 * 60_000 && all.any { c -> c.id == it.channelId } }.minByOrNull { it.start }
            delay(15_000)
        }
    }
    fun switchTo(r: Reminder) {
        saveReminders(reminders - r)
        val ch = all.firstOrNull { it.id == r.channelId } ?: return
        if (ch.categoryId in closed) return
        replay = null; liveAfter = null; backToLive = false; archiveOf = null
        selected = ch.categoryId
        playing = byCategory[ch.categoryId].orEmpty().indexOf(ch).takeIf { it >= 0 } ?: return
        playerKey++
                    Spacer(Modifier.height(12.dp))
                }
                LazyColumn(state = channelList, verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    itemsIndexed(channels, key = { _, c -> c.id }) { i, ch ->
                        LaunchedEffect(ch.id, start) {
                            val cached = epg[ch.id]
                            // Reload when nothing is cached yet or everything cached has ended.
                            if (cached == null || cached.isNotEmpty() && cached.last().end < start + GUIDE_WINDOW) {
                                delay(300) // fast scrolling cancels before the request goes out
                                epg[ch.id] = runCatching { x.shortEpg(ch, limit = 10) }.getOrDefault(emptyList())
                            }
                        }
                        GuideRow(
                            channel = ch,
                            programmes = epg[ch.id],
                            start = start,
                            now = now,
                            favorite = ch.id.toString() in favorites,
                            onClick = { returnTo = null; playing = i },
                            // In "Recently watched" long-press removes the entry instead; focus moves to the next row.
                            onLongClick = {
                                if (selected != RECENT) toggleFavorite(ch)
                                else {
                                    saveRecent(recent - ch.id)
                                    if (channels.size > 1) { returnTo = i.coerceAtMost(channels.size - 2); refocus++ }
                                    else {
                                        selected = loaded.firstOrNull { it.id !in hidden }?.id
                                        scope.launch { awaitFrame(); runCatching { firstCategory.requestFocus() } }
                                    }
                                }
                            },
                            modifier = (if (i == returnTo) Modifier.focusRequester(channelFocus) else Modifier)
                                .onPreviewKeyEvent { e ->
                                    // Right on a catch-up channel opens its recordings, Menu the coming programmes.
                                    when {
                                        e.type != KeyEventType.KeyDown -> false
                                        ch.archiveDays > 0 && e.key == Key.DirectionRight -> { archiveOf = ch; true }
                                        e.key == Key.Menu -> { upcomingOf = ch; true }
                                        else -> false
                                    }
                                },
                        )
                    }
                }
            }
        }
        }
    }
}

